-- 0095: İletişim sayfası gövdesi sadeleşti.
--
-- Sayfaya iletişim kartları ve form eklendiği için gövdedeki adres listesi
-- tekrar ediyordu. Gövde artık "hangi konuda yazmalıyım / yanıt süresi"
-- rehberini taşır; adresler tek yerden (Yönetim → İletişim) gelir.
UPDATE pages
SET detail = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Okuyucularımızdan gelen geri bildirimler yayın kalitemizi geliştiriyor. Haber ihbarı, düzeltme talebi, reklam ve teknik konularda aşağıdaki kanallardan bize ulaşabilirsiniz. Talebinizin konusunu belirtmeniz daha hızlı yanıt almamızı sağlar."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Hangi konuda yazmalıyım?"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Haber ihbarı ve bilgi/belge paylaşımı → haber merkezi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hatalı bilgi, başlık-içerik uyumsuzluğu, yayın etiği → düzeltme."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Reklam, sponsorluk ve iş birliği → reklam birimi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Kişisel veriler ve KVKK başvuruları → KVKK kanalı."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Üyelik, bülten ve site erişimi → teknik destek."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Staj ve açık pozisyonlar → insan kaynakları."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Yanıt süresi"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Haber merkezi 7/24 çalışır. Diğer talepler hafta içi mesai saatlerinde yanıtlanır; resmî tatillerde yanıt süresi uzayabilir. KVKK başvuruları en geç 30 gün içinde yanıtlanır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Kaynağınız gizli kalsın"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "İhbarınızı destekleyen belge, fotoğraf veya bağlantıları mesaja ekleyebilirsiniz. Kimliğinizin paylaşılmamasını istiyorsanız bunu mesajın başında açıkça belirtin; bu durumda yalnızca doğrulama için gerekli asgari bilgi istenir."}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Acil güvenlik veya hayati risk içeren durumlarda lütfen önce 112 Acil Çağrı Merkezi''ni arayın. Sitemiz acil müdahale hizmeti sunmaz."}]}]}]}'::jsonb, updated_at = now()
WHERE slug = 'iletisim';
